with d as (select value r from jsonb_array_elements($q$[{"notes":["Make a double batch and freeze half in a container; they'll keep for a month and reheat beautifully on the stove.","If you can't find lard, use neutral oil or a little butter, though lard gives them the best flavour.","Serve alongside arepas, white rice, or grilled meat.","Cook pork until it reaches at least 70°C in the thickest part (75°C for mince and sausages)."],"id":"a07692d4-ff36-4c9f-91b0-ec860aeb30c4"},{"notes":["Make it ahead: Laabda tastes even better the next day. Cool, cover, and refrigerate for up to 3 days, then reheat gently on the stove.","Scale it up: This recipe doubles easily for big family gatherings. Use a larger pot and add 30 minutes to the braising time.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"steps":[{"text":"Heat the ghee in a large heavy-bottomed pot over medium-high heat. Working in batches, brown the beef on all sides, about 3 minutes per side. Transfer to a plate."},{"text":"Add the sliced onions to the pot and cook, stirring often, until deep golden and caramelized, about 20 minutes. This takes patience, let them colour properly for the sweetness."},{"text":"Add the minced garlic and cook for 1 minute until fragrant."},{"text":"Stir in the cardamom, cinnamon, cloves, turmeric, salt and pepper. Cook for 1 minute."},{"text":"Add the tomato paste and stir to coat the onions, cooking for 2 minutes."},{"text":"Return the beef to the pot along with the water and bay leaves. Bring to a simmer, then reduce heat to low, cover, and braise for 2½ to 3 hours, stirring occasionally. The meat is ready when it's very tender and breaks apart easily, and the sauce is rich and thickened."},{"text":"Taste and adjust seasoning. Serve hot with rice or flatbread."}],"id":"17365db3-20b4-4d9f-9645-4f10a8debb4f"},{"diets":["vegetarian","no-gluten"],"steps":[{"text":"Char the poblanos directly over a gas flame or under a hot grill, turning with tongs, until the skin is blackened all over, about 8 minutes. Place them in a plastic bag, seal it, and let them steam for 5 minutes."},{"text":"Peel off the blackened skin under cool running water. Remove the stem and seeds, then chop the poblano flesh into bite-sized pieces."},{"text":"Heat the oil in a large frying pan over medium heat. Add the onion and cook, stirring, until softened, about 4 minutes. Add the garlic and cook for 1 minute more."},{"text":"Reduce the heat to low. Add the Oaxaca cheese and cheddar in handfuls, stirring constantly until melted and smooth, about 5 minutes. The cheese should be creamy and flowing."},{"text":"Fold in the roasted poblano pieces. Taste and season with salt and pepper."},{"text":"Transfer to a warm serving dish and serve immediately with hot tortilla chips on the side."}],"id":"5eb15f12-a442-4a2d-957b-a9d2aa788fd7"},{"notes":["Olluco releases starch as it cooks, which naturally thickens the sauce. Don't rush it, the longer you simmer, the creamier it becomes.","Make it ahead: this dish tastes even better the next day. Reheat gently over low heat with a splash of milk or water."],"steps":[{"text":"Heat the oil in a large pot over medium heat. Add the onion and cook, stirring, until soft and golden, about 5 minutes."},{"text":"Add the garlic and ají amarillo paste, stirring constantly to combine, about 1 minute. The mixture should be fragrant and bright yellow."},{"text":"Add the olluco, cumin, salt and pepper. Stir to coat the tubers in the ají mixture, about 2 minutes."},{"text":"Pour in just enough water to barely cover the olluco, about 300 ml. Bring to a simmer, then reduce heat to medium-low and cover, cooking until the olluco is tender when pierced with a knife."},{"text":"Cook for 20 minutes, until the olluco is very tender and the liquid has reduced slightly. Stir occasionally to prevent sticking."},{"text":"Pour in the milk and gently stir. Add the crumbled queso fresco and fold in carefully until it begins to melt into the sauce, about 3 minutes."},{"text":"Taste and adjust salt and pepper. The sauce should be creamy and the tubers very soft. Serve hot, scattered with coriander if you like."}],"id":"0159a90f-9c62-46af-a2b0-bdae4b45d2ae"},{"notes":["Use fresh wide rice noodles (from the chilled aisle) for the best texture, they're done the moment they're hot.","The heat matters: your wok needs to be smoking hot when the garlic goes in. This keeps the chicken from stewing.","Add the basil right at the end so it stays bright and fragrant.","Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"id":"8be812a8-e6b8-4b12-9967-feaed671a86c"},{"notes":["Tripe is sold cleaned in most butchers, ask them to confirm it's ready to cook. If you find it tough after 30 minutes, keep simmering until it breaks down easily with a fork.","This keeps well in the fridge for 2 days and tastes better reheated the next day."],"id":"6b3e8ba5-eb48-4b78-835c-f5c3d5c4b849"},{"notes":["The chillies can be charred and peeled up to 4 hours ahead; keep them in a covered container in the fridge until you're ready to stuff them.","If you can't find Oaxaca cheese, fresh mozzarella (torn into chunks) or even grated Oaxaca from a package will work, the key is using cheese that melts easily.","The tomato sauce can be made ahead and reheated gently just before serving."],"id":"4006f058-0f3a-4444-bc91-c92ee3e5a121"},{"notes":["Labskaus is best made with cooked corned beef from a deli or tin. If using homemade, cook it until very tender, then cool before dicing.","Use waxy potatoes like kipfler or baby potatoes; they hold their shape better than floury varieties.","Add a fried egg on top if you'd like the traditional presentation, Anna's Oma always did."],"steps":[{"text":"Heat the oil in a large pot over medium heat. Add the onion and cook, stirring occasionally, until softened and just beginning to colour, about 5 minutes."},{"text":"Add the diced potato and corned beef. Stir to combine and cook for 2 minutes, letting the beef warm through."},{"text":"Pour in the stock and add the bay leaf. Bring to a simmer, then cook uncovered for 12 to 15 minutes, until the potato is tender."},{"text":"Stir in the chopped herring and the herring brine. Cook for another 2 minutes to warm through and let the flavours meld."},{"text":"Taste and adjust seasoning with salt and pepper, remember the herring and brine are already salty."},{"text":"Serve hot in bowls, with dark bread on the side."}],"id":"69832540-38f3-4ecd-8ca0-77a5a1dc448c"},{"notes":["Make the batter up to 2 hours ahead and keep it in the fridge. Shape and fry just before serving.","Don't skip drying the chickpeas, it's what gets them crispy. If they're wet, they'll steam instead."],"steps":[{"text":"Pat the drained chickpeas completely dry with paper towels; this helps them crisp. Mash them roughly in a bowl with a fork, you want some texture, not a smooth paste."},{"text":"Stir through the onion, garlic, parsley, mint, ground coriander, salt and pepper. Add the flour and water and mix until the mixture holds together when squeezed. Let it rest for 5 minutes."},{"text":"With damp hands, shape into 12 flat patties about 6 cm across and 1.5 cm thick. Place on a plate."},{"text":"Heat 60 ml of olive oil in a large heavy-based frying pan over medium-high heat until it shimmers. Working in batches, carefully place 4 fritters into the oil."},{"text":"Fry for 3 to 4 minutes until deep golden and crispy on the first side, then flip and fry for another 3 minutes until the second side is also crispy. Drain on paper towels."},{"text":"Repeat with the remaining fritters, adding more oil to the pan as needed."},{"text":"Serve warm with lemon wedges and extra salt. They're best eaten straight away, while they still crackle."}],"id":"29968c5c-ba25-4194-8859-d0335733bd51"},{"notes":["Make it ahead: braise fully, cool, then refrigerate for up to 2 days. Reheat gently over low heat with a splash of stock.","Swap green olives for kalamata if you prefer, it's richer but still very Tunisian.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"id":"116457e1-7e5b-4bb6-84c0-017d40aa84e9"},{"notes":["Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part."],"id":"8791273a-6245-4bc2-9da9-ccedfebe785c"},{"notes":["Mac salad can be made a few hours ahead and chilled, the flavours improve as it sits.","For a real plate lunch vibe, use a compartment plate. Any firm white rice works; short-grain Japanese-style rice is traditional, but long-grain is just as good.","Prawns cook fast, so watch them carefully. Raw prawns are best, but you can swap in cooked prawns, just heat them through for 1–2 minutes instead.","Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through. Cool any leftover rice quickly and refrigerate it within an hour; reheat it until steaming hot."],"id":"a754ed16-1f73-40f2-a12f-513aa2f94374"},{"notes":["Swap the root veg: swede, beetroot or sweet potato all work. Just keep pieces roughly the same size so they cook evenly.","Use bone-in thighs if that's what's in your trolley, just add 5 minutes to the braise time.","Leftovers are even stickier and better the next day. Reheat gently on the stove with a splash of water.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"id":"41317426-5502-47fa-a7ce-a1ee33d59013"},{"notes":["This dish tastes even better the next day. Refrigerate in an airtight container for up to three days, or freeze for a month.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"id":"0813323a-82ef-417d-a2c7-dc34ae065fdc"},{"notes":["The fermentation time depends on your kitchen temperature: warmer rooms will ferment faster (3 days), cooler ones may take 5 days. Taste the batter after day 3, it should be pleasantly sour, not sharp.","Injera freezes well for up to a month. Layer cooked injera between greaseproof paper, wrap tightly, and thaw at room temperature before serving.","Make injera a day or two before you plan to serve it. It stays soft and slightly chewy when wrapped loosely in a clean cloth."],"steps":[{"text":"Mix teff flour, water and salt in a large bowl. Stir until you have a smooth, thin batter with no lumps, thinner than pancake batter, about the consistency of single cream. Cover loosely with a clean cloth."},{"text":"Let the batter ferment at room temperature for 3 to 5 days. It will develop a slightly sour smell and small bubbles will rise to the surface. Stir it down gently each day. You'll know it's ready when it smells pleasantly sour and tastes a little tangy."},{"text":"After fermentation, stir the batter well. It should still be thin and pourable. If it's too thick, add a little warm water, a tablespoon at a time."},{"text":"Heat a large non-stick frying pan or crepe pan (about 30 cm across) over medium-high heat. Don't oil it, injera cooks on a dry surface."},{"text":"Once the pan is hot, pour about 120 ml of batter into the centre. Quickly tilt and swirl the pan so the batter spreads into a thin, even circle that covers the whole base. Work fast, injera sets quickly."},{"text":"Cook for about 1 to 2 minutes without flipping. The top will start to look spongy and develop small holes. The bottom should be light golden and slightly chewy, not crispy. When the steam stops rising, it's done."},{"text":"Slide the injera onto a plate. Repeat with the remaining batter."},{"text":"Stack the finished injera loosely on a plate or cloth to keep them warm and slightly soft."}],"id":"d84d5fd6-2017-46d7-a9af-2b038c8e9e80"},{"notes":["Make the cashew cream up to 2 days ahead and keep in the fridge; assemble with herbs and walnuts just before serving.","If you don't have raw cashews, use store-bought cashew butter (about 150 g) and skip the soaking step. You'll need a bit less water, start with 60 ml.","Traditionally made with yoghurt; this version is just as creamy, and Layla's family has eaten it both ways for years."],"id":"a0004fab-cb3d-49cf-b578-b9ddd7d3b26e"},{"notes":["Keeps in the fridge for three days. Reheat gently in a pot over low heat, or microwave in a covered bowl.","Make it a day ahead: the flavour deepens overnight.","Freeze the cooled braised ribs in the sauce for up to three months.","Food safety: Steaks and roasting cuts of beef or lamb can be served pink: about 60°C in the centre is medium-rare, 70°C is well done."],"steps":[{"text":"Blanch the short ribs: bring a large pot of water to the boil, add the ribs and boil for 3 minutes. Drain and rinse the ribs under cold running water, scrubbing gently to remove any scum. Pat dry."},{"text":"Heat a heavy-based braising pot or large Dutch oven over medium-high heat. Add 1 tbsp of the sesame oil. Working in batches, brown the ribs on all sides, about 10 minutes total. Transfer to a plate."},{"text":"Return the pot to medium heat and add the remaining sesame oil. Add the garlic and ginger, stirring for 30 seconds until fragrant."},{"text":"Return the ribs to the pot. Add the soy sauce, water, honey, spring onions, drained shiitake mushrooms (reserving the soaking liquid) and jujubes. Pour in 100 ml of the mushroom soaking liquid. Bring to a boil, then reduce heat to low, cover, and simmer gently for 1.5 to 2 hours, until the ribs are completely tender and the meat pulls easily from the bone."},{"text":"Remove the pot from the heat. Discard the spring onions, garlic and ginger pieces (or leave them in if you prefer). Taste and season with salt if needed, the soy sauce will likely be salty enough."},{"text":"Serve the short ribs hot in shallow bowls with the braising liquid spooned over. Scatter with toasted sesame seeds. Serve with steamed white rice and kimchi on the side."}],"id":"7b7aa56b-bee1-43c3-9905-b5c45692cd6b"},{"notes":["Kuah lkor is gentler than laksa, if you like more heat, add a sliced green chilli or two to the paste.","The tamarind paste keeps the broth light and stops it feeling too rich; don't skip it.","Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"id":"30052fa8-fae6-4c6e-8d25-13ee92d39b63"},{"steps":[{"text":"Toast the sesame seeds in a heavy-bottomed pan over medium heat, stirring constantly, until fragrant and lightly golden, about 5 minutes. Tip onto a plate."},{"text":"Pour the honey into the same pan over medium heat. Warm, swirling gently, until it turns a deep amber, about 8 minutes. Don't stir it, just let it happen. You'll know it's ready when it smells toasted and a drop in cold water snaps cleanly."},{"text":"Remove from heat. Working fast, add the vanilla and salt, then tip in the toasted sesame seeds. Stir hard until everything is coated."},{"text":"Pour onto a baking tray lined with baking paper, spreading it thin and even with an oiled spatula. Work quickly, it sets fast."},{"text":"Cool completely at room temperature, about 2 hours. Break into pieces with your hands. That's it, mate."}],"id":"450c022b-b790-49df-9243-574ab5f4cf92"},{"notes":["Fresh fish cakes are best if you can find them at an Asian grocer. Canned work fine too, just drain them well.","The shrimp paste makes this dish. It's pungent and funky on its own, but dissolves into the broth and gives it depth.","If you can't find fresh Vietnamese mint, use extra Thai basil or regular mint, it won't be the same, but it still works."],"steps":[{"text":"In a small bowl, mash the shrimp paste with a fork until it breaks down. Add 2 tbsp of hot water and stir well until it dissolves into a pungent liquid; set aside."},{"text":"Heat 1 tbsp oil in a large pot over medium heat. Add the minced garlic and sliced chillies, stirring constantly until fragrant, about 1 minute."},{"text":"Add the shrimp paste liquid to the pot and stir for another minute, until fragrant, letting the flavour bloom. Pour in the stock and bring to a simmer until bubbling gently."},{"text":"Add the fish sauce and caster sugar, stirring to dissolve. Taste and adjust, it should be salty, pungent, and slightly sweet. This is Huế food; don't be timid."},{"text":"Gently slide the fish cake slices into the simmering broth and cook for 5 to 8 minutes until they're heated through and tender."},{"text":"While the broth cooks, divide the cooked rice vermicelli between four bowls."},{"text":"Ladle the hot broth and fish cakes over the noodles. Top with fresh Vietnamese mint, coriander, and spring onion. Serve with lime wedges and extra chillies on the side for those who want more heat."}],"id":"461116e3-cd67-4ab5-b854-7d174e0232c3"},{"notes":["Serve with white rice and farofa (toasted cassava flour) on the side to soak up the sauce.","Any firm white fish works, barramundi, snapper, ling or flathead are all good choices. Avoid delicate fish like flake.","Make ahead: prep the vegetables and fish the day before; cook just before serving so the fish stays tender.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part."],"steps":[{"text":"Heat the dendê oil in a large, heavy-bottomed pot over medium-high heat. Add the onion and capsicum, stirring occasionally, until softened and the onion is starting to caramelize, about 8 minutes."},{"text":"Add the garlic and chilli, stirring constantly for 1 minute until fragrant."},{"text":"Stir in the tomato paste and cook for 1 minute to deepen the flavour."},{"text":"Pour in the coconut milk and fish stock, stirring to combine. Bring to a gentle simmer until small bubbles break the surface, then reduce the heat to medium-low."},{"text":"Carefully add the fish chunks to the pot, season with salt and pepper, and simmer gently for 12 to 15 minutes, until the fish is just cooked through and flakes easily. Do not stir vigorously; gently turn the fish once halfway through."},{"text":"Taste and adjust seasoning if needed. Serve hot, scattered with fresh coriander and lime wedges on the side."}],"id":"52320754-6ad1-4672-9de1-c4b8d8b56fa0"},{"notes":["This freezes brilliantly, make a double batch and freeze the cooled stir-fry in containers for a quick weeknight reheat. Thaw overnight in the fridge and warm in a pan over medium heat.","Use any frozen mixed veg (broccoli, carrot, capsicum, snap peas all work), or what's on special.","Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"steps":[{"text":"Heat 1 tbsp oil in a large wok or frying pan over high heat. Add the chicken strips and cook, stirring often, until cooked through (no pink inside), about 5 minutes. Transfer to a plate."},{"text":"Add the remaining oil to the pan. Add the frozen mixed vegetables and stir-fry for 2 minutes until starting to soften."},{"text":"Pour in the stir-fry sauce and honey, stirring to combine. Return the chicken to the pan and toss everything together until well coated and hot, about 1 minute."},{"text":"Divide rice or noodles between bowls, top with the stir-fry while the chicken is glossy and cooked through, and garnish with spring onion and sesame seeds if using."}],"id":"0dc5dad8-7f07-46ac-9f8a-f9b8dbfb809f"},{"notes":["Cime di rapa can be hard to find outside Italian delis, but gai lan (Chinese broccoli) works just as well, it's the same plant, just called by a different name.","Serve with a generous pour of your best olive oil and crusty bread to wipe the bowl."],"steps":[{"text":"Bring a large pot of salted water to the boil. Add the orecchiette and cook until al dente, about 12 minutes."},{"text":"While the pasta cooks, heat the olive oil in a large frying pan over medium heat. Add the garlic and chilli, and cook gently for 2–3 minutes, stirring often, until the garlic just turns golden, don't let it burn."},{"text":"Add the cime di rapa to the pan with a splash of water (about 100 ml) and a pinch of salt. Increase the heat to medium-high and cook, stirring occasionally, until the greens are tender, about 8 minutes."},{"text":"Reserve 200 ml of the pasta cooking water, then drain the pasta. Add it to the pan with the cime di rapa."},{"text":"Toss well, adding pasta water a little at a time, until everything is coated in a loose, silky sauce. The starch in the water helps emulsify the oil. Taste and adjust the salt and pepper."},{"text":"Serve hot, with a scatter of flaky salt if you like, and more chilli on the side for anyone who wants it."}],"id":"ae9fd6e1-e654-4535-950d-01d0f85250b5"},{"notes":["Food safety: Cook whole cuts of beef, lamb and pork to at least 63°C in the thickest part, then rest for 3 minutes; cook pork and any rolled or stuffed cuts until the juices run clear. Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part."],"steps":[{"text":"Heat the oil in a large shallow pan over medium-high heat. Season the fish pieces with salt and pepper on both sides."},{"text":"Fry the fish for 2 minutes each side until lightly golden, then remove to a plate."},{"text":"In the same pan, sauté the garlic until fragrant, about 1 minute. Add the sliced onion and cook, stirring, until soft and translucent, about 4 minutes."},{"text":"Pour in the soy sauce and vinegar, stirring to combine. Bring to a gentle simmer until small bubbles appear and the sharp vinegar smell has softened."},{"text":"Return the fish to the pan, nestling the pieces among the onions. Simmer gently for 5–7 minutes, spooning the sauce over the fish occasionally, until the fish is cooked through and flakes easily when tested with a fork."},{"text":"Taste and adjust the salt if needed. Serve hot with the braising liquid and onions spooned over the fish, alongside steamed white rice."}],"id":"cbf409ab-0276-47e0-a275-92f596aea6a0"},{"notes":["Siraegi keeps well in the fridge for 3 days and can be served hot, warm or at room temperature.","If you can't find dried radish greens, look for them in Asian markets labelled as 'siraegi' or 'siraegi', they're worth seeking out."],"id":"23ab88a1-88bb-4b4c-80a9-ad5cf34f9979"},{"notes":["This works best on a gas burner where you can crank the heat. The wok needs to be hot enough that the curry paste caramelises rather than steams.","If you don't have Thai basil, regular basil works, or just serve it plain with rice.","Scale up easily: use 400g chicken for two plates, but keep cooking time about the same, high heat, 8–10 minutes total.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"steps":[{"text":"Heat your wok or heavy frying pan over high heat until it's smoking hot, about 2 minutes."},{"text":"Pour in the oil and swirl it around. It should shimmer immediately."},{"text":"Add the garlic and chillies. Stir for 15 seconds until fragrant."},{"text":"Add the chicken pieces, breaking them up with your spatula. Let them sit for 30 seconds without moving, you want them to catch colour."},{"text":"Stir and cook for 2 minutes until the chicken is mostly cooked through and the edges are starting to char."},{"text":"Add the curry paste, fish sauce and palm sugar. Toss everything together for another 2 minutes. You're looking for the paste to caramelise into the chicken and the whole thing to smell fierce."},{"text":"Taste and adjust the salt and heat if you need to. The chicken should be cooked through (75°C inside), with charred, sticky edges."},{"text":"Serve straight onto a plate with jasmine rice and fresh Thai basil if you have it."}],"id":"aec00c06-c1d1-412b-9594-10ec09e1b86d"},{"notes":["For a fully vegan dish, use soy sauce instead of fish sauce and check that your curry paste and coconut milk are vegan-certified.","You can prep all the vegetables ahead of time. Layer them in the pot just before cooking.","Leftovers keep well for 2 days in the fridge. Reheat gently on the stove with a splash of water."],"steps":[{"text":"Heat the oil in a clay pot (or heavy-bottomed pot) over medium heat. Add the curry paste and sliced garlic, stirring gently until fragrant, about 2 minutes."},{"text":"Pour in the coconut milk, vegetable stock, fish sauce and palm sugar. Stir well and let it come to a gentle simmer until bubbling lightly and the palm sugar has melted."},{"text":"Layer the noodles evenly over the curry sauce. Don't stir, just press them down gently so they're submerged."},{"text":"Layer the potato slices over the noodles, then add the mushrooms, capsicum and bok choy in separate layers on top. Pour any remaining sauce over everything."},{"text":"Cover the pot and simmer gently for 20 to 25 minutes, until the potatoes are tender and the noodles have absorbed the sauce. Peek at it after 15 minutes, it should smell deeply fragrant."},{"text":"Gently stir everything together just before serving. Taste and adjust the seasoning. Serve hot, topped with fresh Thai basil and coriander if you have them."}],"id":"6cb69a61-c448-49f7-bd17-539d4455d64a"},{"notes":["Saltfish needs to be soaked overnight to remove excess salt. If you're short on time, use 400 g fresh white fish fillet instead, add it to the stew in the last 5 minutes of cooking.","Green fig is unripe plantain, boiled until tender. Look for it in Caribbean or Latin markets, or swap for potato or sweet potato.","The stew tastes better the next day. Keep it in the fridge for up to 3 days and reheat gently on the stove."],"id":"f7072873-77df-431f-ae68-26f0de06fe46"},{"notes":["The batter can be made several hours ahead and chilled.","The apple compote keeps in the fridge for up to 3 days and can be gently reheated.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"id":"bb908603-bef9-4730-88a7-a5454a5f9297"},{"notes":["The balance of tamarind to palm sugar is personal. Start with equal parts and adjust to taste, some prefer it more sour, others more rounded.","Make the vegetable stock a day ahead if you can; let it chill overnight so any sediment sinks to the bottom, and the broth will be clearer."],"steps":[{"text":"Bring the vegetable stock to a gentle simmer in a large pot. Stir in the tamarind paste and palm sugar until dissolved, about 2 minutes. Taste and adjust the balance of sour and sweet, it should brighten your tongue but not overwhelm it."},{"text":"Add the pumpkin slices and simmer for 5 minutes until they are just tender but still hold their shape."},{"text":"Add the mushrooms and tofu cubes. Simmer gently for 8 minutes, stirring occasionally, until the mushrooms are soft and the tofu has absorbed some of the broth's flavour."},{"text":"Add the tomato wedges and season with salt and black pepper. Simmer for 2 more minutes until the tomatoes are softened, the tomatoes should be warm but still hold their shape."},{"text":"Remove from heat and stir through most of the fresh dill and coriander, reserving some for serving. Taste once more and adjust the seasoning if needed."},{"text":"Ladle into bowls and garnish with the remaining herbs and red chilli slices if using. Serve at once, while the broth is still steaming."}],"id":"007e4b00-3d49-4aee-b221-6e18ebeecd0a"}]$q$::jsonb)), up as (update public.published_recipes p set recipe = p.recipe || (d.r - 'id' - 'notes') || case when d.r ? 'notes' then jsonb_build_object('notes', coalesce((select jsonb_agg(n) from jsonb_array_elements(d.r->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)) else '{}'::jsonb end, diets = case when d.r ? 'diets' then array(select jsonb_array_elements_text(d.r->'diets')) else p.diets end from d where p.id=(d.r->>'id')::uuid returning p.id) select (select count(*) from d) expected, (select count(*) from up) updated;